cat > main_test.ts <<'EOF'
import { report } from "./main.ts";

function assertEquals(actual: string[], expected: string[]) {
  if (JSON.stringify(actual) != JSON.stringify(expected)) {
    throw new Error(`expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

Deno.test("empty ledger", () => {
  assertEquals(report(["ledger 0"]), ["TOTAL 0.00"]);
});

Deno.test("balances sorted by balance desc, then account bytes asc", () => {
  assertEquals(
    report([
      "ledger 6",
      "bob debit 3.07",
      "alice credit 41.50",
      "carol credit 0.10",
      "carol debit 0.10",
      "b credit 0.10",
      "Z credit 0.10",
    ]),
    ["alice 41.50", "Z 0.10", "b 0.10", "carol 0.00", "bob -3.07", "TOTAL 38.63"],
  );
});

Deno.test("unknown kind reports first bad line only", () => {
  assertEquals(
    report(["ledger 3", "x credit 1.00", "y refund 2.00", "z bogus 1.00"]),
    ["ERROR line 2"],
  );
});

Deno.test("negative fractions under one unit", () => {
  assertEquals(report(["ledger 1", "a debit 0.05"]), ["a -0.05", "TOTAL -0.05"]);
});
EOF
deno test 2>&1 | tail -3

